#' Plot an INTERACT iGraph for a Single Sample
#'
#' @description Takes an `igraph` object generated by `BuildGraph()`
#' and renders a static network graph using iGraph
#'
#' @param graph A directed `igraph` object generated by `BuildGraph()`.
#' @param interactions Optional. The full interactions data frame from RunINTERACT.
#' Required only if performing gene-level highlighting.
#' @param highlight.cell Optional. Character string of a cell type to highlight.
#' @param highlight.gene Optional. Character string of a ligand or receptor gene symbol to highlight.
#' @param highlight.color Character. Hex code or color name for highlighted elements. Default is red.
#' @param top.n Optional integer. Number of top population-level edges to display.
#'
#' @return A ggraph/ggplot object.
#' @export
PlotGGraph = function(graph, interactions = NULL, highlight.cell = NULL, highlight.gene = NULL, highlight.color = "#DC0000FF", top.n = NULL) {

  if (is.null(graph)) return(NULL)

  # Extract sample ID stored in the graph object
  sample.id = graph$sample.id

  # 1. Prepare Graph for Plotting ----
  # Remove autocrine self-loops (sender == receiver) to avoid ggraph memory crash
  plot.graph = igraph::simplify(graph, remove.multiple = FALSE, remove.loops = TRUE)

  # Filter to top.n population-level edges if requested
  if (!is.null(top.n)) {
    edge.weights = igraph::E(plot.graph)$weight
    if (length(edge.weights) > top.n) {
      threshold = sort(edge.weights, decreasing = TRUE)[top.n]
      plot.graph = igraph::subgraph.edges(plot.graph, which(edge.weights >= threshold), delete.vertices = TRUE)
    }
  }

  # 2. Identify Edges and Nodes to Highlight ----

  # Get edge list as dataframe for mapping
  edge.list = igraph::as_data_frame(plot.graph, what = "edges")
  is.highlighted = rep(FALSE, nrow(edge.list))

  # Gene-based highlighting (requires interactions table)
  if (!is.null(highlight.gene)) {
    if (is.null(interactions)) {
      message("Note: highlight.gene provided but interactions table is NULL. Skipping gene highlighting.")
    } else {
      # Use grepl for robustness (handles complexes like COMPLEX:IL6_IL6ST)
      highlight.edges = interactions %>%
        dplyr::filter(sample == sample.id) %>%
        dplyr::filter(grepl(paste0("\\b", highlight.gene, "\\b"), source_genesymbol) |
                        grepl(paste0("\\b", highlight.gene, "\\b"), target_genesymbol))

      if (!is.null(highlight.cell)) {
        highlight.edges = highlight.edges %>%
          dplyr::filter(sender == highlight.cell | receiver == highlight.cell)
      }

      # Map back to the graph's sender-receiver pairs
      highlight.pairs = highlight.edges %>%
        dplyr::select(from = "sender", to = "receiver") %>%
        dplyr::distinct() %>%
        dplyr::mutate(match.found = TRUE)

      # Join with graph edges and convert to logical
      joined = dplyr::left_join(edge.list, highlight.pairs, by = c("from", "to"))
      is.highlighted = !is.na(joined$match.found)
    }
  } else if (!is.null(highlight.cell)) {
    # Cell-only highlighting (all inbound and outbound edges)
    is.highlighted = edge.list$from == highlight.cell | edge.list$to == highlight.cell
  }

  # 3. Handle Edge Weights Safely ----
  # To prevent memory crashes, we normalize weights and rename the attribute
  # so ggraph doesn't perform automatic high-magnitude mapping.
  raw.weights = edge.list$weight
  max.w = max(raw.weights, na.rm = TRUE)

  # Scale weights to a safe visual range.
  # We use a higher baseline (0.5) to ensure even the thinnest edges are clearly visible.
  scaled.thickness = (raw.weights / max.w) * 1.5 + 0.5

  # Assign cleaned attributes to the graph object
  igraph::E(plot.graph)$is.highlighted = as.character(is.highlighted)
  igraph::E(plot.graph)$scaled.thickness = scaled.thickness

  # Delete the original "weight" attribute to bypass ggraph's automatic mapping bug
  plot.graph = igraph::delete_edge_attr(plot.graph, "weight")

  if (!is.null(highlight.cell)) {
    igraph::V(plot.graph)$node.highlighted = igraph::V(plot.graph)$name == highlight.cell
  } else {
    igraph::V(plot.graph)$node.highlighted = FALSE
  }
  
  igraph::V(plot.graph)$node.size.category = as.character(igraph::V(plot.graph)$is.tumor | igraph::V(plot.graph)$node.highlighted)
  igraph::V(plot.graph)$node.highlighted.char = as.character(igraph::V(plot.graph)$node.highlighted)

  # Pre-calculate the layout explicitly using igraph to guarantee stability
  # We use weights = NA here to ensure the layout is purely topological
  safe.layout = igraph::layout_with_fr(plot.graph, weights = NA)

  # 4. Render Plot ----
  subtitle.text = dplyr::case_when(
    !is.null(highlight.cell) & !is.null(highlight.gene) ~ paste0("Highlighted: ", highlight.cell, " & ", highlight.gene),
    !is.null(highlight.cell) ~ paste0("Highlighted Cell Type: ", highlight.cell),
    !is.null(highlight.gene) ~ paste0("Highlighted Gene: ", highlight.gene),
    !is.null(top.n) ~ paste0("Top ", top.n, " Population Interactions"),
    TRUE ~ "Ecosystem Overview"
  )

  static.plot = ggraph::ggraph(plot.graph, layout = safe.layout) +

    # Edges with dynamic highlighting and weight-proportional thickness
    # Using geom_edge_link0 to avoid grid pathAttr arrow interpolation crash
    ggraph::geom_edge_link0(
      ggplot2::aes(
        edge_color = is.highlighted,
        edge_alpha = is.highlighted,
        edge_width = scaled.thickness
      ),
      arrow = grid::arrow(length = grid::unit(2.5, "mm"), type = "closed") # Slightly larger arrows
    ) +

    # Mapping the highlight aesthetics for edges
    # Non-highlighted edges are set to gray50 for structural visibility
    ggraph::scale_edge_color_manual(values = c("TRUE" = highlight.color, "FALSE" = "gray50")) +
    ggraph::scale_edge_alpha_manual(values = c("TRUE" = 1.0, "FALSE" = 0.3)) +

    # Control the continuous scale of the edge widths
    # Increased the range to c(0.8, 4.0) to make the ecosystem network much easier to view
    ggraph::scale_edge_width_continuous(range = c(0.8, 4.0), guide = "none") +

    # Nodes with highlighting (size boost for tumor or highlighted cell)
    ggraph::geom_node_point(
      ggplot2::aes(color = name, size = node.size.category)
    ) +

    # Labels with clean plain fontface
    ggraph::geom_node_text(
      ggplot2::aes(label = name),
      fontface = "plain",
      color = "black",
      repel = TRUE,
      size = 3.5
    ) +

    # Clean aesthetics
    ggplot2::scale_size_manual(values = c("TRUE" = 12, "FALSE" = 5), guide = "none") +
    ggsci::scale_color_igv(name = "Cell Type") +
    ggraph::theme_graph() +
    ggplot2::labs(title = sample.id, subtitle = subtitle.text) +
    ggplot2::theme(legend.position = "none")

  return(static.plot)
}
